#!/bin/bash
# Grok CLI character concepts (concept/direction only, never shipped). One run per art direction, in parallel.
cd "$(dirname "$0")"
G=~/.grok/bin/grok
WORKER="OUR dock worker (see ref/our-worker.png, the 4th figure from the left and the close-up on the right): a stocky, muscular harbour worker, broad shoulders, thick forearms, big hands in yellow work gloves, blue short-sleeve T-shirt, bright yellow bib overalls with dark navy knee bands, brown work boots, yellow hard hat, curly brown hair, thick brown moustache, friendly determined face. Keep exactly this outfit and these colours."
gen() { # $1 id, $2 style
  $G --always-approve -p "Generate ONE image (landscape 16:9) and save it as $1-concept.png in this folder (convert to PNG if needed). Do not edit or delete any other file. Use ref/$1-ship.png (a real in-engine render of the orange tugboat and the forklift from our game's model pack) as the reference for the ship, the forklift, the scale and the rendering style: the tug must look like that tug. $WORKER Scene: the worker stands full-body on the concrete quay in the foreground-left, 3/4 view, one hand resting on a wooden crate, the orange tugboat moored right behind him and the small forklift beside him, harbour water visible. The worker is about 1.8 m tall: the tug's bridge towers far above him. ART STYLE (this is the point of the image): $2 No text, no logos, no watermark, no UI." > "log-$1.txt" 2>&1; }
gen 1-golden-hour "premium stylised realism like Sea of Thieves and Tchia: stylised proportions (head about 1/6.5 of height, chunky hands), soft painterly textures, warm low golden-hour sun from the side, cool blue soft shadows, rim light on the shoulders, gentle atmospheric haze, clear turquoise water with soft foam." &
gen 2-miniature "soft matte miniature diorama like Tiny Glade and Townscaper: the worker looks like a handcrafted toy figurine (head about 1/4 of height, rounded simple forms, mitten-like hands), soft bright overcast-ish daylight, big soft ambient occlusion, pastel cream and mint palette, mint-green calm water, strong tilt-shift depth of field so it reads as a tiny model." &
gen 3-ink-cel "bold cel-shaded comic look like Hi-Fi Rush and The Wind Waker: thick dark ink outlines, exactly two flat tones per colour with a hard shadow edge, saturated colours, hard sharp shadows, big expressive shapes (head about 1/4.5 of height, huge hands and forearms), vivid blue toon sea with crisp white foam shapes, bright blue sky with flat-shaded cumulus." &
gen 4-ponyo-coast "Studio Ghibli inspired anime look like Ponyo, Kiki's Delivery Service and Ni no Kuni: soft cel shading with painted blue-violet shadows, delicate warm brown line art, watercolour paper texture, towering white cumulus clouds over the sea, luminous turquoise water, warm summer light (head about 1/5 of height, gentle rounded features)." &
gen 5-glossy-toybox "glossy saturated co-op toy look like Astro Bot and It Takes Two: everything has a clean glossy plastic sheen with bright specular highlights and clear-coat rims, very saturated candy colours, bright clean sunlight, soft contact shadows, chubby bouncy proportions (head about 1/3.5 of height, big round hands), candy-aqua water." &
gen 6-lantern-dusk "moody graphic dusk like Firewatch and Dredge: low orange sun near the horizon, strong layered gradient fog that flattens the distance into poster-like bands, deep teal water reflecting the orange sky, purple-blue shadows, warm sodium dock lamps starting to glow, simplified graphic shapes, slightly lean adult proportions (head about 1/6 of height)." &
wait
